#!/usr/bin/env python3
"""RED-PHASE route-table audit: every HTTPRoute in the gitops tree has a SecurityPolicy (P0-016).

Contract source:
  - output/test-artifacts/test-design/test-design-qa.md  (P0-016, FR-38, R-002)
  - gitops/envoy-gateway/base/envoy-gateway.yaml         (hpdc-edge Gateway + hpdc-edge-domain-routes)
  - gitops/security/base/api-key-authn.yaml              (SecurityPolicies)
  - gitops/telemetry-ingestion/base/telemetry-ingestion.yaml
  - gitops/entity-store/base/graphql-gateway.yaml
  - gitops/observability/base/envoy-ui-routes.yaml       (UI routes, native-auth annotations)
  - gitops/tool-ui/base/tool-ui-routes.yaml              (UI routes, native-auth annotations)

RED PHASE: every test is @pytest.mark.skip. The audit encodes the strict security
contract (R-002): every HTTPRoute/GRPCRoute must be protected by a matching
SecurityPolicy targetRef. Today several routes are only protected by
gateway.envoyproxy.io/native-auth annotations (UI routes) or not covered at all
(e.g. hpdc-telemetry-http-ingestion, hpdc-graphql-gateway, and envoy-ui-routes.yaml
is not even referenced by its overlay kustomization) - those deviations keep the
contract tests red until the route table is hardened.

Run under pytest (all tests are skipped). main() does NOT run the audit bodies.
"""

from __future__ import annotations

import re
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[3]
GITOPS = ROOT / "gitops"

ROUTE_KINDS = {"HTTPRoute", "GRPCRoute", "TCPRoute"}
SECURITY_POLICY_KIND = "SecurityPolicy"
NATIVE_AUTH_ANNOTATION = "gateway.envoyproxy.io/native-auth"


def _gitops_yaml_files() -> list[Path]:
    return sorted(GITOPS.glob("*/base/*.yaml")) + sorted(GITOPS.glob("*/overlays/*/kustomization.yaml"))


def _documents(text: str) -> list[str]:
    return [doc for doc in re.split(r"(?m)^---\s*$", text) if doc.strip()]


def _doc_kind(doc: str) -> str | None:
    match = re.search(r"(?m)^kind:\s*(\S+)", doc)
    return match.group(1) if match else None


def _doc_metadata(doc: str) -> tuple[str | None, str | None]:
    name = namespace = None
    in_metadata = False
    for line in doc.splitlines():
        if line.strip() == "metadata:":
            in_metadata = True
            continue
        if in_metadata:
            if line and not line[0].isspace():
                in_metadata = False
            else:
                match = re.match(r"\s+name:\s*(\S+)", line)
                if match and name is None:
                    name = match.group(1)
                match = re.match(r"\s+namespace:\s*(\S+)", line)
                if match and namespace is None:
                    namespace = match.group(1)
    return name, namespace


def _doc_annotations(doc: str) -> dict[str, str]:
    annotations: dict[str, str] = {}
    in_annotations = False
    for line in doc.splitlines():
        if line.strip() == "annotations:":
            in_annotations = True
            continue
        if in_annotations:
            if line and not line[0].isspace():
                break
            match = re.match(r"\s+([\w./-]+):\s*(.*)", line)
            if match and match.group(1) not in annotations:
                annotations[match.group(1)] = match.group(2).strip().strip("\"'")
    return annotations


def _security_policy_targets(doc: str) -> list[dict[str, str]]:
    targets: list[dict[str, str]] = []
    current: dict[str, str] = {}
    in_target = False
    for line in doc.splitlines():
        if line.strip() == "targetRef:":
            in_target = True
            current = {}
            continue
        if in_target:
            if line and not line[0].isspace():
                in_target = False
                targets.append(current)
                current = {}
            else:
                match = re.match(r"\s+(group|kind|name|namespace):\s*(\S+)", line)
                if match:
                    current[match.group(1)] = match.group(2)
    if in_target:
        targets.append(current)
    return targets


def _api_key_auth_block(doc: str) -> str:
    index = doc.find("apiKeyAuth:")
    return doc[index:] if index != -1 else ""


def _api_key_paths(block: str) -> list[str]:
    return [m.group(1) for m in re.finditer(r"(?m)^\s+value:\s*(/\S+)", block)]


def _api_key_headers(block: str) -> list[str]:
    return [m.group(1) for m in re.finditer(r"(?m)^\s+name:\s*([A-Za-z0-9-]+)", block)]


def _collect_routes() -> list[dict[str, str]]:
    routes: list[dict[str, str]] = []
    for path in _gitops_yaml_files():
        for doc in _documents(path.read_text(encoding="utf-8")):
            kind = _doc_kind(doc)
            if kind in ROUTE_KINDS:
                name, namespace = _doc_metadata(doc)
                routes.append(
                    {
                        "kind": kind,
                        "name": name or "",
                        "namespace": namespace or "",
                        "file": str(path),
                        "doc": doc,
                    }
                )
    return routes


def _collect_policies() -> list[dict[str, str]]:
    policies: list[dict[str, str]] = []
    for path in _gitops_yaml_files():
        for doc in _documents(path.read_text(encoding="utf-8")):
            if _doc_kind(doc) == SECURITY_POLICY_KIND:
                for target in _security_policy_targets(doc):
                    policies.append({**target, "file": str(path), "doc": doc})
    return policies


# P0-016 (FR-38, R-002)
# Given: every gateway route must authenticate  When: the gitops tree is audited
# Then:  every HTTPRoute/GRPCRoute has a SecurityPolicy targetRef matching its
#        name and namespace (no unauthenticated route; R-002)
@pytest.mark.skip(reason="RED PHASE: P0-016 route-table audit asserts a SecurityPolicy per route; UI routes currently rely on native-auth annotations and several routes are uncovered")
def test_every_http_grpc_route_has_security_policy() -> None:
    routes = _collect_routes()
    assert routes, "no routes found in gitops tree"
    policies = _collect_policies()
    for route in routes:
        if route["kind"] == "TCPRoute":
            continue  # TCP is terminated at the gateway; SecurityPolicy is HTTP/GRPC scoped
        matched = any(
            policy.get("kind") == route["kind"]
            and policy.get("name") == route["name"]
            and policy.get("namespace") in (route["namespace"], None)
            for policy in policies
        )
        # Known deviations currently tolerated (documented, must be closed in green phase):
        #   - hpdc-edge-observability-ui-routes / tool-ui / grafana-hubble routes use
        #     gateway.envoyproxy.io/native-auth=true instead of a SecurityPolicy.
        #   - hpdc-telemetry-http-ingestion and hpdc-graphql-gateway have no coverage.
        assert matched, (
            f"{route['kind']} {route['name']} in {route['namespace']} has no SecurityPolicy "
            f"targetRef (R-002). File: {route['file']}"
        )


# P0-016 (FR-38, R-002)
# Given: messaging routes /events and /telemetry must authenticate via X-API-Key
#        natively at Envoy Gateway (FR-38, credential isolation R-009)
# When:  the SecurityPolicy set is inspected
# Then:  hpdc-messaging-api-key-authn covers the hpdc-edge-domain-routes HTTPRoute
#        and hpdc-telemetry-grpc-api-key-authn covers the gRPC ingestion route
@pytest.mark.skip(reason="RED PHASE: P0-016 credential-isolation contract not yet live (B-001)")
def test_messaging_routes_covered_by_api_key_policy() -> None:
    policies = _collect_policies()
    api_key_doc = (GITOPS / "security/base/api-key-authn.yaml").read_text(encoding="utf-8")
    auth_block = _api_key_auth_block(api_key_doc)

    messaging = next((p for p in policies if p.get("name") == "hpdc-messaging-api-key-authn"), None)
    assert messaging is not None, "hpdc-messaging-api-key-authn SecurityPolicy missing"
    assert messaging.get("kind") == "HTTPRoute"
    assert messaging.get("name") == "hpdc-edge-domain-routes"
    assert messaging.get("namespace") == "envoy-gateway-system"
    assert set(_api_key_paths(auth_block)) >= {"/events", "/telemetry"}
    assert set(_api_key_headers(auth_block)) >= {"X-API-Key"}

    grpc = next((p for p in policies if p.get("name") == "hpdc-telemetry-grpc-api-key-authn"), None)
    assert grpc is not None, "hpdc-telemetry-grpc-api-key-authn SecurityPolicy missing"
    assert grpc.get("kind") == "GRPCRoute"
    assert grpc.get("name") == "hpdc-telemetry-grpc-ingestion"
    assert grpc.get("namespace") == "telemetry-ingestion"


# P0-016 (FR-38, R-002)
# Given: a SecurityPolicy targetRef must reference a real route  When: the audit runs
# Then:  every SecurityPolicy targetRef resolves to an existing route in the tree
@pytest.mark.skip(reason="RED PHASE: P0-016 route-table audit not yet satisfied (B-001)")
def test_no_dangling_security_policy_targets() -> None:
    routes = _collect_routes()
    route_keys = {(route["kind"], route["name"], route["namespace"]) for route in routes}
    for policy in _collect_policies():
        key = (policy.get("kind"), policy.get("name"), policy.get("namespace"))
        assert key in route_keys, (
            f"SecurityPolicy {policy.get('name')} targetRef dangles: "
            f"{policy.get('kind')}/{policy.get('name')}/{policy.get('namespace')}"
        )


# P0-016 (FR-38, R-002)
# Given: the hpdc-edge Gateway is the single ingress  When: routes are audited
# Then:  every HTTPRoute/GRPCRoute attaches to hpdc-edge in envoy-gateway-system,
#        and the gateway never exposes plaintext HTTP to the data plane (80 redirects
#        to 443; 1884 is the mTLS-scoped MQTT listener)
@pytest.mark.skip(reason="RED PHASE: P0-016 route-table audit not yet satisfied (B-001)")
def test_all_routes_attach_to_hpdc_edge_gateway() -> None:
    for route in _collect_routes():
        if route["kind"] == "TCPRoute":
            continue
        doc = route["doc"]
        assert "parentRefs:" in doc, f"{route['name']} must declare parentRefs"
        assert "name: hpdc-edge" in doc, f"{route['name']} must attach to the hpdc-edge gateway"
        assert "namespace: envoy-gateway-system" in doc, f"{route['name']} parentRef must resolve to envoy-gateway-system"
    gateway = (GITOPS / "envoy-gateway/base/envoy-gateway.yaml").read_text(encoding="utf-8")
    assert "kind: Gateway" in gateway and "name: hpdc-edge" in gateway
    assert "protocol: HTTPS" in gateway and "port: 443" in gateway
    http_redirect = re.search(r"name: http-redirect.*?protocol: HTTP.*?toPort: 443", gateway, re.S)
    assert http_redirect, "port 80 must redirect to 443 and never serve the data plane"
    assert "port: 1884" in gateway, "MQTT TCP listener (1884) must be declared for the telemetry ingress"


# P0-016 (FR-38, R-002)
# Given: GitOps is the only source of truth (R-001)  When: route manifests are audited
# Then:  every base file defining a route kind is referenced by its component overlay
#        kustomization, otherwise the route is never deployed (drift)
@pytest.mark.skip(reason="RED PHASE: P0-016 audit flags envoy-ui-routes.yaml unreferenced by the observability overlay kustomization (R-001 drift)")
def test_route_manifests_referenced_by_overlays() -> None:
    for base in sorted(GITOPS.glob("*/base/*.yaml")):
        text = base.read_text(encoding="utf-8")
        if not any(f"kind: {kind}" in text for kind in ROUTE_KINDS):
            continue
        component = base.parents[1].name
        overlays = sorted((GITOPS / component / "overlays").glob("*/kustomization.yaml"))
        assert overlays, f"no overlay kustomization for component {component} (routes would never deploy)"
        referenced = any(
            base.name in ks.read_text(encoding="utf-8")
            or f"../../{component}/base" in ks.read_text(encoding="utf-8")
            for ks in overlays
        )
        # Known deviation: gitops/observability/base/envoy-ui-routes.yaml is NOT listed
        # in gitops/observability/overlays/dev/kustomization.yaml (only
        # observability-ui-routes.yaml + grafana-hubble-routes.yaml are).
        assert referenced, f"route manifest {base} not referenced by any {component} overlay kustomization (R-001)"


def main() -> int:
    # RED PHASE: all tests carry @pytest.mark.skip; the audit bodies must not run
    # standalone (skip markers are honoured by pytest only).
    print("RED PHASE - skipped (run under pytest; all tests carry @pytest.mark.skip)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""RED-PHASE secret scan: no secrets in Git; InfisicalSecret CRDs for real secrets (P0-022).

Contract source:
  - output/test-artifacts/test-design/test-design-qa.md  (P0-022, NFR21, R-008)
  - gitops/infisical/base/infisical.yaml                 (Infisical operator / CSI driver / rotation)
  - gitops/security/base/api-key-authn.yaml              (dev-only messaging-api-keys Secret)
  - gitops/casdoor/base/casdoor.yaml, gitops/backstage/base/backstage.yaml

RED PHASE: every test is @pytest.mark.skip. The scan asserts the NFR21 contract: no
high-entropy or production credential material is committed, prod overlays never carry
plaintext Secrets, and real secrets are provisioned through InfisicalSecret /
ExternalSecret CRDs. Dev-only credentials are explicitly allowlisted below and marked
as known exceptions that must migrate to Infisical in the green phase.

Run under pytest (all tests are skipped). main() does NOT run the scan bodies.
"""

from __future__ import annotations

import re
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[3]
GITOPS = ROOT / "gitops"

# Known dev-only credentials tolerated in base manifests today. Each entry is a known
# exception (R-008): they must move behind InfisicalSecret before production.
DEV_ONLY_CREDENTIALS = {
    "hpdc-events-dev-key",        # gitops/security/base/api-key-authn.yaml - dev-only messaging API key
    "hpdc-telemetry-dev-key",     # gitops/security/base/api-key-authn.yaml - dev-only telemetry API key
    "InfisicalAdmin12345",        # gitops/infisical/base/infisical.yaml - dev bootstrap DB password
    "CasdoorAdmin12345",          # gitops/casdoor/base/casdoor.yaml - dev bootstrap admin password
    "backstage-client-secret",    # gitops/backstage/base/backstage.yaml - placeholder client secret
    "backstage-backend-secret",   # gitops/backstage/base/backstage.yaml - placeholder signing secret
}

HIGH_ENTROPY_PATTERNS = [
    re.compile(r"[0-9a-f]{40,}"),                     # long hex blobs
    re.compile(r"[A-Za-z0-9+/]{48,}={0,2}"),          # long base64 blobs
    re.compile(r"AKIA[0-9A-Z]{16}"),                  # AWS access key ids
    re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH |PGP )?PRIVATE KEY-----"),  # private keys
]

SECRET_KEY_PATTERN = re.compile(
    r"(?i)(password|passwd|pwd|token|apikey|api[-_]?key|secret|client[-_]?secret|private[-_]?key|authorization|credential)"
)

DEV_CRED_VALUES = ("hpdc-events-dev-key", "hpdc-telemetry-dev-key", "InfisicalAdmin12345", "CasdoorAdmin12345")


def _documents(text: str) -> list[str]:
    return [doc for doc in re.split(r"(?m)^---\s*$", text) if doc.strip()]


def _doc_kind(doc: str) -> str | None:
    match = re.search(r"(?m)^kind:\s*(\S+)", doc)
    return match.group(1) if match else None


def _inline_key_values(doc: str) -> list[tuple[str, str]]:
    return [
        (m.group(1), m.group(2).strip())
        for m in re.finditer(r"(?m)^\s*([A-Za-z0-9_.-]+):\s*(\S.*)$", doc)
    ]


def _base_yamls() -> list[Path]:
    return sorted(GITOPS.glob("*/base/*.yaml"))


def _all_yamls() -> list[Path]:
    return sorted(GITOPS.rglob("*.yaml"))


# P0-022 (NFR21, R-008)
# Given: credentials must never be committed  When: the gitops tree is scanned
# Then:  no high-entropy hex/base64 blobs, cloud access keys, or private key material
#        appear outside the allowlisted dev-only credentials
@pytest.mark.skip(reason="RED PHASE: P0-022 secret scan not yet green; requires InfisicalSecret adoption for real credentials (R-008)")
def test_no_high_entropy_secret_material_in_gitops() -> None:
    for path in _base_yamls():
        text = path.read_text(encoding="utf-8")
        for pattern in HIGH_ENTROPY_PATTERNS:
            for match in pattern.findall(text):
                assert match in DEV_ONLY_CREDENTIALS, (
                    f"possible secret material {match[:16]}... found in {path}"
                )


# P0-022 (NFR21, R-008)
# Given: production credentials must not be derived from dev values  When: the prod
#        overlays are scanned  Then: no plaintext Secret with data/stringData exists
#        and no dev credential value leaks into the prod environment
@pytest.mark.skip(reason="RED PHASE: P0-022 scan asserts prod overlays carry no plaintext secrets; verification pending (R-008)")
def test_prod_overlays_contain_no_plaintext_secrets() -> None:
    for ks_path in sorted(GITOPS.glob("*/overlays/prod/kustomization.yaml")):
        for resource in re.findall(r"(?m)^\s*-\s+(.+\.yaml)\s*$", ks_path.read_text(encoding="utf-8")):
            target = (ks_path.parent / resource).resolve()
            if not target.is_file():
                continue
            for doc in _documents(target.read_text(encoding="utf-8")):
                if _doc_kind(doc) == "Secret" and re.search(r"(?m)^\s*(stringData|data):", doc):
                    raise AssertionError(f"plaintext Secret in prod overlay: {target}")
                assert not any(cred in doc for cred in DEV_CRED_VALUES), (
                    f"dev credential value leaked into prod overlay {target}"
                )


# P0-022 (NFR21, R-008)
# Given: ConfigMaps are not secret stores  When: ConfigMap documents are scanned
# Then:  secret-bearing keys never carry real values (only allowlisted dev placeholders)
@pytest.mark.skip(reason="RED PHASE: P0-022 scan not yet green; requires secrets migrated out of plaintext (R-008)")
def test_configmaps_hold_no_secret_values() -> None:
    for path in _base_yamls():
        for doc in _documents(path.read_text(encoding="utf-8")):
            if _doc_kind(doc) != "ConfigMap":
                continue
            for key, value in _inline_key_values(doc):
                if SECRET_KEY_PATTERN.search(key):
                    assert value in DEV_ONLY_CREDENTIALS or value.startswith(("{{", "<", "your-")), (
                        f"ConfigMap {path} holds secret-like key {key!r} with value {value!r}"
                    )


# P0-022 (NFR21, R-008)
# Given: the only Secret committed to git is the dev messaging-api-keys store
# When:  all kind: Secret documents are scanned
# Then:  every stringData/data value is an allowlisted dev-only credential and the
#        store carries no unexpected keys (expansion is flagged)
@pytest.mark.skip(reason="RED PHASE: P0-022 scan not yet green; additional Secrets in git would fail (R-008)")
def test_dev_secret_stringdata_only_known_exceptions() -> None:
    for path in _base_yamls():
        for doc in _documents(path.read_text(encoding="utf-8")):
            if _doc_kind(doc) != "Secret":
                continue
            if not re.search(r"(?m)^\s*(stringData|data):", doc):
                continue
            for key, value in _inline_key_values(doc):
                if SECRET_KEY_PATTERN.search(key) or key in ("events-key", "telemetry-key"):
                    assert value in DEV_ONLY_CREDENTIALS, (
                        f"Secret {path} stores non-allowlisted credential {key}={value!r}"
                    )


# P0-022 (NFR21, R-008)
# Given: Infisical is the secrets management plane  When: the Infisical operator
#        manifest is inspected  Then: secretRotation, auditLog, operator and csiDriver
#        are all enabled so real credentials can be injected at runtime
@pytest.mark.skip(reason="RED PHASE: P0-022 Infisical wiring not yet verified end-to-end (B-001)")
def test_infisical_operator_enabled() -> None:
    infisical = (GITOPS / "infisical/base/infisical.yaml").read_text(encoding="utf-8")
    assert "kind: ConfigMap" in infisical and "name: infisical-config" in infisical
    for feature in ("secretRotation", "auditLog", "operator", "csiDriver"):
        assert re.search(rf"(?m)^\s+{feature}:\s*\n\s+enabled:\s*true", infisical), (
            f"Infisical {feature} must be enabled"
        )


# P0-022 (NFR21, R-008)
# Given: production credentials must be provisioned via Infisical CRDs, never committed
# When:  the gitops tree is scanned for secret sources
# Then:  at least one InfisicalSecret / ExternalSecret CRD exists to hold real
#        credentials (currently absent - the red contract the implementation must close)
@pytest.mark.skip(reason="RED PHASE: P0-022 expects InfisicalSecret/ExternalSecret CRDs in gitops; none exist yet (R-008)")
def test_infisicalsecret_or_externalsecret_present() -> None:
    for path in _all_yamls():
        if re.search(r"(?m)^kind:\s*(InfisicalSecret|ExternalSecret|InfisicalSecretTemplate)\b", path.read_text(encoding="utf-8")):
            return
    raise AssertionError(
        "no InfisicalSecret/ExternalSecret CRD in gitops - production credentials must "
        "not be committed in plaintext (R-008)"
    )


def main() -> int:
    # RED PHASE: all tests carry @pytest.mark.skip; the scan bodies must not run
    # standalone (skip markers are honoured by pytest only).
    print("RED PHASE - skipped (run under pytest; all tests carry @pytest.mark.skip)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
